import { useEffect } from "react";

export default function WhySec() {

  useEffect(() => {
    const boxes = document.querySelectorAll('.box');

    boxes.forEach((box) => {
      const clickHandler = () => {
        boxes.forEach((b) => b.classList.remove('expanded'));
        box.classList.add('expanded');
      };
      box.addEventListener('click', clickHandler);
      box._handler = clickHandler;
    });

    return () => {
      boxes.forEach((box) => {
        if (box._handler) {
          box.removeEventListener('click', box._handler);
        }
      });
    };
  }, []);

  return (
    <section className="why-sec">
      <div className="container">
        <div className="row">
          <div className="col-md-4">
            <div className="heading">
              <h2>Why GroLinq?</h2>
              <p>Choose GROLINQ to transform your digital presence into a powerful engine for sustainable success.</p>
            </div>
          </div>

          <div className="col-md-8">
            <div className="textslider">

              <div className="box expanded">
                <h4>Data-Driven Insights</h4>
                <p>Leverage millions of verified data points to optimize strategy & maximize impact.</p>
              </div>

              <div className="box">
                <h4>Strategic Connections</h4>
                <p>Building meaningful partnerships that create market value.</p>
              </div>

              <div className="box">
                <h4>Measurable Growth</h4>
                <p>Clear, trackable metrics that prove results and drive scale.</p>
              </div>

            </div>
          </div>

        </div>
      </div>
    </section>
  );
}
